<x-filament-panels::page>
    <form
        class="cat-workspace cat-editor"
        wire:submit="save"
        x-data="{
            editorId: @js($this->getId()),
            uploading: false,
            progress: 0,
            dragging: false,
            uploadError: '',
            completeUpload() {
                this.uploading = false;
                this.dragging = false;
                if (this.$refs.photos) this.$refs.photos.value = '';
            },
            validateSelection(event) {
                const files = Array.from(event.target.files || []);
                if (!files.length) return;
                let message = '';
                if (this.uploading) message = 'Espera a que termine la carga actual.';
                else if (files.length + this.$wire.gallery.length > {{ config('catalog.max_images') }}) message = 'Puedes añadir hasta {{ config('catalog.max_images') }} fotografías por producto.';
                else if (files.some(file => file.size > {{ config('catalog.upload_max_kb') * 1024 }})) message = 'Cada fotografía puede pesar hasta {{ config('catalog.upload_max_kb') / 1024 }} MB.';
                else if (files.some(file => file.type && !['image/jpeg', 'image/png', 'image/webp'].includes(file.type))) message = 'Selecciona fotografías JPG, PNG o WebP.';
                if (message) {
                    event.stopImmediatePropagation();
                    event.target.value = '';
                    this.uploadError = message;
                } else {
                    this.uploadError = '';
                }
            }
        }"
        x-on:livewire-upload-start="uploadError = ''; uploading = true; progress = 0"
        x-on:livewire-upload-finish="completeUpload()"
        x-on:livewire-upload-error="completeUpload(); uploadError = 'No se pudo completar la carga. Revisa las fotos y tu conexión e inténtalo otra vez.'"
        x-on:livewire-upload-cancel="completeUpload()"
        x-on:livewire-upload-progress="progress = $event.detail.progress"
        x-on:catalog-photos-processed.window="if ($event.detail.editorId === editorId) { completeUpload(); uploadError = $event.detail.error || ''; }"
        x-on:catalog-editor-invalid.window="if ($event.detail.editorId === editorId) $nextTick(() => $refs.errors?.scrollIntoView({ behavior: 'smooth', block: 'center' }))"
        x-on:submit.capture="if (uploading) { $event.preventDefault(); $event.stopImmediatePropagation(); }"
    >
